<script>
  const { class: klass, from, company = '' } = $props()

  const string = $derived.by(() => {
    const thisYear = new Date().getFullYear()
    if (!from) return `${thisYear}`

    const fromYear = new Date(from).getFullYear()
    if (fromYear === thisYear) return `${thisYear}`
    return `${fromYear}-${thisYear}`
  })
</script>

<div class={klass}>
  <span>Copyright &copy;</span>
  <span>{company}</span>
  <span>{string}</span>
</div>
